-- Content catalog only: learner history and session snapshots are untouched.
begin;
create table if not exists public.content_lessons (
 id text primary key,
 position integer not null check (position >= 0),
 status text not null default 'draft' check (status in ('draft','published','archived')),
 data jsonb not null check (jsonb_typeof(data) = 'object' and data->>'id' is not null and data->>'id' = id),
 updated_at timestamptz not null default now()
);
create table if not exists public.content_items (
 id text primary key,
 lesson_id text not null references public.content_lessons(id),
 skill text not null check (skill in ('vocabulary','grammar','phrases','writing','listening','reading')),
 position integer not null check (position >= 0),
 status text not null default 'draft' check (status in ('draft','published','archived')),
 data jsonb not null check (jsonb_typeof(data) = 'object' and data->>'id' is not null and data->>'id' = id and data->>'lessonId' is not null and data->>'lessonId' = lesson_id and data->>'skill' is not null and data->>'skill' = skill),
 updated_at timestamptz not null default now()
);
create index if not exists content_items_lesson_position on public.content_items(lesson_id, position);
alter table public.content_lessons enable row level security;
alter table public.content_items enable row level security;
revoke all on public.content_lessons, public.content_items from anon, authenticated;
grant select on public.content_lessons, public.content_items to anon, authenticated;
drop policy if exists published_lessons on public.content_lessons;
create policy published_lessons on public.content_lessons for select to anon, authenticated using (status = 'published');
drop policy if exists published_items on public.content_items;
create policy published_items on public.content_items for select to anon, authenticated using (status = 'published' and exists(select 1 from public.content_lessons l where l.id = lesson_id and l.status = 'published'));
create or replace function public.touch_content_updated_at() returns trigger language plpgsql set search_path = public as $$begin new.updated_at = now(); return new; end;$$;
drop trigger if exists content_lessons_updated on public.content_lessons;
create trigger content_lessons_updated before update on public.content_lessons for each row execute function public.touch_content_updated_at();
drop trigger if exists content_items_updated on public.content_items;
create trigger content_items_updated before update on public.content_items for each row execute function public.touch_content_updated_at();
commit;
